    const bundle = readFileSync(join(process.cwd(), "dist", "client.js"), "utf8");
    // load id = 完整包名（浏览器端模块注册契约）
    expect(bundle).toContain('id: "@wingsky-1/dsh-xiaozhuge"');
    // 契约外壳：factory(require) 注入 external 依赖
