    const m = clientSrc.match(/BOOT_MESSAGE_HEAD\s*=\s*"([^"]+)"\s*\+\s*\n\s*"([^"]+)"/);
    expect(m).not.toBeNull();
    expect(`${m![1]}${m![2]}`).toBe(serverHead);
  });
});

